"  // Touchpad Workspace Swipe Gesture (Two-finger horizontal swipe)
  let lastWorkspaceSwitchTime = 0;
  const SWITCH_COOLDOWN = 800; // ms
  const SWIPE_THRESHOLD = 40; // higher threshold for deliberate swiping

  // Prevent browser-native horizontal scroll on the viewport (fixes trackpad layout shift bug)
  const viewport = document.getElementById('workspaces-viewport');
  if (viewport) {
    viewport.addEventListener('scroll', () => {
      if (viewport.scrollLeft !== 0) {
        viewport.scrollLeft = 0;
      }
    });
  }

  window.addEventListener('wheel', (e) => {
    // Ignore swipe gestures inside any window, taskbar, or start menu
    if (e.target.closest('.window') || e.target.closest('#taskbar') || e.target.closest('#start-menu')) {
      return;
    }

    // Ensure horizontal scroll is dominant to avoid accidental triggers during vertical scrolls
    if (Math.abs(e.deltaX) > Math.abs(e.deltaY) * 2 && Math.abs(e.deltaX) > SWIPE_THRESHOLD) {
      // Prevent browser's default horizontal scroll and history navigation (back/forward)
      e.preventDefault();

      const now = Date.now();
      if (now - lastWorkspaceSwitchTime > SWITCH_COOLDOWN) {
        if (e.deltaX > 0) {
          // Swipe left (scroll right) -> next workspace
          switchWorkspace(state.activeWorkspaceIndex + 1);
        } else {
          // Swipe right (scroll left) -> previous workspace
          switchWorkspace(state.activeWorkspaceIndex - 1);
        }
        lastWorkspaceSwitchTime = now;
      }
    }
  }, { passive: false });
}"

